INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷七十六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bd256224ade10807719cc5b9dd08151101a79e9c/content/books/zizhi-tongjian/vol-281/year-0937/part-01/sources/library/jiuwudaishi-076-937-january-a/source.txt", "note": "《旧五代史》卷七十六，段落 jiu-wudaishi-205deb4a7860-p001895；EPUB电子本，纸本及异文待核", "id": "cf87c948-5fa1-54df-881e-493e1aa29908"}, {"title": "旧五代史·卷七十六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bd256224ade10807719cc5b9dd08151101a79e9c/content/books/zizhi-tongjian/vol-281/year-0937/part-01/sources/library/jiuwudaishi-076-937-january-b/source.txt", "note": "《旧五代史》卷七十六，段落 jiu-wudaishi-205deb4a7860-p001896；EPUB电子本，纸本及异文待核", "id": "275b8bae-916d-5eca-8770-e010d3f7f032"}, {"title": "资治通鉴·后晋纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bd256224ade10807719cc5b9dd08151101a79e9c/content/books/zizhi-tongjian/vol-281/year-0937/part-01/sources/library/tongjian-281-937-opening/source.txt", "note": "《资治通鉴》后晋纪二，段落 zizhi-tongjian-a63549944a71-p003338；电子底本待考，分段待核", "id": "d8972aeb-e6f1-58da-b10d-e505fe0b0cfc"}, {"title": "新五代史·卷六十二", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bd256224ade10807719cc5b9dd08151101a79e9c/content/books/zizhi-tongjian/vol-281/year-0937/part-01/sources/library/xinwudaishi-062-937-qi/source.txt", "note": "《新五代史》卷六十二，段落 xin-wudaishi-b08f244b9241-p003128；EPUB电子本，纸本及异文待核", "id": "94c6c4e8-bc50-5a2c-a456-36a6b61fe3f0"}, {"title": "旧五代史·卷94·秘琼传", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b603079e/content/books/zizhi-tongjian/vol-280/year-0936/part-09/sources/library/jiuwudaishi-094-mi-qiong/source.txt", "note": "《旧五代史》卷94·秘琼传，段落 jiu-wudaishi-205deb4a7860-p002306；已核上下文及传主，纸本及异文待核。", "id": "73547d25-2885-5ab6-aeb9-dbb4949c4134"}, {"title": "新五代史·卷8·晋高祖纪·天福二年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b603079e/content/books/zizhi-tongjian/vol-280/year-0936/part-09/sources/library/xinwudaishi-008-lu-date/source.txt", "note": "《新五代史》卷8·晋高祖纪·天福二年，段落 xin-wudaishi-b08f244b9241-p000315；已核上下文及传主，纸本及异文待核。", "id": "82c9d12b-cb16-517a-a2b9-084a79a37f6a"}]'::jsonb)
