INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "安重荣", "aliases": ["安重榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安重荣，转投者。", "biography": null, "status": "draft", "id": "7309cd08-206a-5781-8eaa-527f54f64299"}, {"name": "秘琼", "aliases": ["秘瓊", "祕瓊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：秘琼，平山籍、牙内都虞侯、受倚者。", "biography": null, "status": "draft", "id": "8ce65f13-6a07-5795-bdb6-565c3af0ff0d"}, {"name": "王景崇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋官员。937年担任引进使，受命劝秘琼接受任命。史书记载他是邢州人。", "biography": null, "status": "draft", "id": "5f673eda-0daa-5174-926f-dca3e0982614"}, {"name": "赵思温", "aliases": ["趙思溫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：赵思温，平州人、拒行回应者。", "biography": null, "status": "draft", "id": "6d48dbcb-e174-55d5-895a-98e065e6f82c"}, {"name": "李崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：李崧。", "biography": null, "status": "draft", "id": "42727c37-29c7-534f-b0f7-900992c16def"}, {"name": "吕琦", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平四年条所见人物：吕琦。", "biography": null, "status": "draft", "id": "8ffb1307-35a3-50aa-b656-645eee4c0395"}, {"name": "范延光", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：范延光。", "biography": null, "status": "draft", "id": "6889e460-4b23-5243-9441-b5c3a78da98f"}, {"name": "张生（范延光所遇术士）", "aliases": ["张生"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "范延光所信任的术士，史书只称他为张生。他对范延光的仕途和梦境作出预测；其具体姓名和活动年份尚不清楚。", "biography": null, "status": "draft", "id": "7994f71f-f54a-5b19-af2f-b81a149f864a"}, {"name": "李从珂", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：李从珂。", "biography": null, "status": "draft", "id": "0a45ab01-e475-5d82-9a76-16d916af5abd"}, {"name": "赵德钧", "aliases": ["趙德鈞", "李绍斌", "李紹斌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：赵德钧。", "biography": null, "status": "draft", "id": "cfda6466-f577-56a2-8851-65b57edb7d3e"}, {"name": "桑维翰", "aliases": ["桑維翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：桑维翰，主张自全、求援者。", "biography": null, "status": "draft", "id": "5132e50a-3ce2-55d5-8f89-fdccd6bf4f02"}, {"name": "杨琏", "aliases": ["楊璉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成三年条所见人物：杨琏，获封江都王者。", "biography": null, "status": "draft", "id": "4975dc84-c87f-5d7f-b1e7-3254e45440ea"}, {"name": "徐氏（杨琏妃）", "aliases": ["徐知诰女"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐知诰（后来的李昪）的女儿，937年嫁给吴太子杨琏。此段没有记载她的名字。", "biography": null, "status": "draft", "id": "aaef797d-c1e0-5687-85cb-0a95bb652cb3"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "徐玠", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：徐玠。", "biography": null, "status": "draft", "id": "70906153-ef05-55ab-b89f-58cf163dfda3"}, {"name": "周宗", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：周宗。", "biography": null, "status": "draft", "id": "155e76cd-ab0e-5e2a-a791-43d64ebe4669"}, {"name": "周廷玉", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴国官员，黟县人。937年由内枢判官出任徐知诰政权的内枢使。", "biography": null, "status": "draft", "id": "e958b1b6-2b55-553f-945b-aff7fb17e4ae"}, {"name": "杨溥", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷270贞明五年条所见人物：杨溥。", "biography": null, "status": "draft", "id": "c9c313a8-8feb-5442-a006-67b9f78d476b"}, {"name": "卢文进", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：卢文进。", "biography": null, "status": "draft", "id": "ead2e914-83dd-5f41-bf9a-5956fbd149ab"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "史书记载正月乙卯发生日食", "start_year": 937, "end_year": 937, "time_original": "937年正月乙卯", "dynasty": "五代十国", "description": "《资治通鉴》记载，天福二年正月乙卯发生日食。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a3a031ff-153c-55d8-a0bc-a7594e77bd92"}, {"title": "石敬瑭任命安重荣为成德节度使、秘琼为齐州防御使", "start_year": 937, "end_year": 937, "time_original": "937年正月，具体日期未记载", "dynasty": "五代十国", "description": "石敬瑭任命安重荣为成德节度使、秘琼为齐州防御使。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ee5ef68d-b7b8-5547-a6c0-4a50fa2991ab"}, {"title": "王景崇受命劝秘琼接受任命", "start_year": 937, "end_year": 937, "time_original": "937年正月，具体日期未记载", "dynasty": "五代十国", "description": "石敬瑭派引进使王景崇向秘琼说明利害。史书随后记载秘琼没有拒绝任命；王景崇是邢州人。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1c3dd9fd-396a-5ed1-b8b4-25a828f8e19e"}, {"title": "安重荣与赵思温到镇州，秘琼没有拒绝任命", "start_year": 937, "end_year": 937, "time_original": "937年正月，具体日期未记载", "dynasty": "五代十国", "description": "安重荣与赵思温到镇州，秘琼没有拒绝任命。", "phases": [], "location_name": "镇州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "62a35393-8908-536c-8151-440697a21313"}, {"title": "安重荣奏报已到任", "start_year": 937, "end_year": 937, "time_original": "937年正月丙辰", "dynasty": "五代十国", "description": "安重荣奏报已到任。", "phases": [], "location_name": "镇州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "91e341b7-aab6-544a-876c-5332fde0e7fb"}, {"title": "契丹把幽州设为南京", "start_year": 937, "end_year": 937, "time_original": "937年正月，具体日期未记载", "dynasty": "五代十国", "description": "契丹把幽州设为南京。此处保留历史地名，不把它与今天的南京市混为一处。", "phases": [], "location_name": "幽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "fcc5cca3-81b0-575a-a592-a4a0eb8b12a8"}, {"title": "李崧和吕琦曾躲藏在伊阙民间", "start_year": null, "end_year": null, "time_original": "937年正月任官条前追述，躲藏的起止日期未记载", "dynasty": "五代十国", "description": "李崧和吕琦曾躲藏在伊阙民间。", "phases": [], "location_name": "伊阙", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "fd41cc88-6881-5f27-9e04-38f4db810ff1"}, {"title": "石敬瑭感谢李崧过去的帮助，也没有追究吕琦", "start_year": 937, "end_year": 937, "time_original": "937年正月，具体日期未记载", "dynasty": "五代十国", "description": "石敬瑭感谢李崧过去的帮助，也没有追究吕琦。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e68a377e-a677-5ed7-8eae-ca5b4f2f7a23"}, {"title": "石敬瑭任命吕琦为秘书监", "start_year": 937, "end_year": 937, "time_original": "937年正月乙丑", "dynasty": "五代十国", "description": "石敬瑭任命吕琦为秘书监。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "74537fa5-3924-553c-9180-7418c7199b4f"}, {"title": "李崧被任命为兵部侍郎并掌管户部事务", "start_year": 937, "end_year": 937, "time_original": "937年正月丙寅", "dynasty": "五代十国", "description": "李崧被任命为兵部侍郎并掌管户部事务。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "96673969-d964-5b5a-8a7c-5254ffcdc572"}, {"title": "范延光相信术士张生的预测，并产生称帝的念头", "start_year": null, "end_year": null, "time_original": "追述范延光早年及显贵后的经历，具体年份未记载", "dynasty": "五代十国", "description": "史书记载，术士张生曾预测范延光会做将相。范延光显贵后十分信任他，又请他解释蛇进入腹中的梦。张生把梦说成帝王征兆，范延光因此产生了称帝的念头。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ee2d0926-2009-5233-bab2-221ec3de8f7f"}, {"title": "赵德钧战败后，范延光从辽州回魏州并上表请降", "start_year": 936, "end_year": 936, "time_original": "追述936年赵德钧战败后的经历，具体日期未记载", "dynasty": "五代十国", "description": "赵德钧战败后，范延光从辽州回魏州并上表请降。", "phases": [], "location_name": "辽州至魏州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "88a5f4ee-2b73-5fd8-98df-a6bd953bfbb3"}, {"title": "范延光秘密写信拉拢秘琼一起作乱，秘琼没有答复", "start_year": null, "end_year": null, "time_original": "937年正月杀秘琼之前的经历，写信日期未记载", "dynasty": "五代十国", "description": "范延光秘密写信拉拢秘琼一起作乱，秘琼没有答复。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5849776c-15a9-5a4f-bbf7-c7a5ce6a5adc"}, {"title": "范延光派兵在夏津杀死秘琼", "start_year": 937, "end_year": 937, "time_original": "937年正月，具体日期未记载", "dynasty": "五代十国", "description": "秘琼前往齐州，途中经过魏州辖境。史书记载，范延光为灭口，也贪图秘琼携带的财物，派兵在夏津拦截并杀死他。", "phases": [], "location_name": "夏津", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "40db6e43-343d-5208-a5eb-10145b7be68c"}, {"title": "范延光奏称秘琼被捕盗兵误杀，石敬瑭没有追究", "start_year": 937, "end_year": 937, "time_original": "937年正月丁卯", "dynasty": "五代十国", "description": "范延光向朝廷报告，称夏津捕盗兵误杀了秘琼。石敬瑭没有追究。史书前文已记范延光主动派兵杀人，因此“误杀”保留为奏报中的说法。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5e8a5818-0fc7-5776-bdbb-ae3c1c944f33"}, {"title": "李崧出任宰相并兼任枢密使", "start_year": 937, "end_year": 937, "time_original": "937年正月戊寅", "dynasty": "五代十国", "description": "李崧出任宰相并兼任枢密使。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "537eff75-7235-5b22-8f8d-0e500a602349"}, {"title": "桑维翰兼任枢密使", "start_year": 937, "end_year": 937, "time_original": "937年正月戊寅", "dynasty": "五代十国", "description": "桑维翰兼任枢密使。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "50947aea-0fc3-51de-ad3f-4f80004a6fe8"}, {"title": "后晋初年藩镇不安，财政和民生困难", "start_year": 937, "end_year": 937, "time_original": "937年正月，具体日期未记载", "dynasty": "五代十国", "description": "史书记载，后晋刚建立时，不少藩镇尚未归服，归服者也有不安。战乱耗尽府库，百姓生活困苦，契丹又不断索求。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8405887a-061e-53c6-aaf6-7ae16845f9fd"}, {"title": "桑维翰建议安抚藩镇、维持契丹关系并发展生产贸易", "start_year": 937, "end_year": 937, "time_original": "937年正月，具体日期未记载", "dynasty": "五代十国", "description": "桑维翰建议石敬瑭以诚意安抚藩镇、放下旧怨，以谦辞厚礼维持与契丹的关系；同时训练军队、整修兵器